# ==============================================================================# 047_ALERT_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# ALERT TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS alerts(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    source TEXT,    severity TEXT,    title TEXT,    description TEXT,    status TEXT)""")conn.commit()# ==============================================================================# LIMPA ALERTAS ABERTOS# ==============================================================================cur.execute("DELETE FROM alerts WHERE status='OPEN'")conn.commit()alerts = []# ==============================================================================# HEALTH# ==============================================================================cur.execute("""SELECT healthFROM runtime_monitorORDER BY id DESCLIMIT 1""")row = cur.fetchone()health = row["health"] if row else 0if health < 70:    alerts.append((        "RUNTIME",        "CRITICAL",        "SYSTEM HEALTH",        f"Health crÃ­tico ({health:.2f}%).",        "OPEN"    ))elif health < 95:    alerts.append((        "RUNTIME",        "WARNING",        "SYSTEM HEALTH",        f"Health reduzido ({health:.2f}%).",        "OPEN"    ))# ==============================================================================# REGRAS PRONTAS# ==============================================================================cur.execute("""SELECTrule_name,priorityFROM rule_engineWHERE status='READY'""")for row in cur.fetchall():    alerts.append((        "RULE_ENGINE",        row["priority"],        row["rule_name"],        "Regra aguardando orquestraÃ§Ã£o.",        "OPEN"    ))# ==============================================================================# COMANDOS PENDENTES# ==============================================================================cur.execute("""SELECT COUNT(*)FROM command_busWHERE status='PENDING'""")pending = cur.fetchone()[0]if pending > 0:    alerts.append((        "COMMAND_BUS",        "HIGH",        "PENDING COMMANDS",        f"{pending} comandos aguardando processamento.",        "OPEN"    ))# ==============================================================================# TAREFAS PENDENTES# ==============================================================================cur.execute("""SELECT COUNT(*)FROM task_queueWHERE status='PENDING'""")tasks = cur.fetchone()[0]if tasks > 0:    alerts.append((        "TASK_QUEUE",        "NORMAL",        "PENDING TASKS",        f"{tasks} tarefas pendentes.",        "OPEN"    ))# ==============================================================================# SALVAR# ==============================================================================for alert in alerts:    cur.execute("""    INSERT INTO alerts(        created_at,        source,        severity,        title,        description,        status    )    VALUES(?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        alert[0],        alert[1],        alert[2],        alert[3],        alert[4]    ))conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================print("="*80)print("ALERT ENGINE")print("="*80)cur.execute("""SELECTseverity,source,title,statusFROM alertsORDER BYCASE severityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'WARNING' THEN 3WHEN 'NORMAL' THEN 4WHEN 'LOW' THEN 5END,id""")rows = cur.fetchall()if not rows:    print("NENHUM ALERTA ATIVO")else:    for row in rows:        print(            f"{row['severity']:<10}"            f"{row['source']:<15}"            f"{row['title']:<30}"            f"{row['status']}"        )print("="*80)cur.execute("SELECT COUNT(*) FROM alerts")print("TOTAL ALERTAS:", cur.fetchone()[0])print("="*80)conn.close()

